\operatorname{Sub}^i(\operatorname{Bind}_h(b,H,E),n,s)=
\begin{cases}
\operatorname{Bind}_h(b,H',E),&i=j\land b=n,\\
\operatorname{Bind}_h(b,H',\operatorname{Sub}^i(E,n,s)),&\neg(i=j\land b=n)\land b\notin FV^j(s),\\
\operatorname{Bind}_h(z,H',\operatorname{Sub}^i(\operatorname{Sub}^j(E,b,\mathsf{Var}_j(z)),n,s)),&\neg(i=j\land b=n)\land b\in FV^j(s).
\end{cases}

Sub^i(beta_\omega(b,K,A,B),n,s)=
\begin{cases}
beta_\omega(b,K',A,B'),&i=a\land b=n,\\
beta_\omega(b,K',Sub^i(A,n,s),B'),&\neg(i=a\land b=n)\land b\notin FV^a(s),\\
beta_\omega(z,K',Sub^i(Sub^a(A,b,tvar(z)),n,s),B'),&\neg(i=a\land b=n)\land b\in FV^a(s).
\end{cases}

